import {characterPanel,inventoryPanel,watchPanel,creationChoices,choiceDialog,peoplePicker,inspectedPerson,comparisonCard} from './ui-panels.js';
import {equipmentPreview,itemBonuses} from './equipment-model.js';
import {mountWorld,captureVisual,animateResult,playBattleBeat,clearBattleBeat} from './world-view.js';
import {applyBattleFrame,transitionFor} from './motion-model.js';
import {sceneTransition,waitForBeat,reducedMotion,toggleMotion} from './cinematics.js';
import {enemyLayout,biomeAt,BIOMES} from './journey-view-model.js';
import {Game,ITEMS,MODS,learned,display,phase,phaseName} from './engine.js';
const root=document.getElementById('app'),KEY='eastward.save.v1';let data,g,panel=null,selectedRace='human',selectedJob='driver',timer=null,sound=false,travelStarted=0,selectedEnemy=null,pendingCommand=null,combatMenu='root',presentation=null,busy=false,playbackController=null,playbackLabel='';
const ui={personId:null,slot:'全部',itemId:null,shopItemId:null,watchId:null,picker:null,feedback:'',scrollCompare:false};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const img=(path,alt='',cls='')=>`<img src="assets/${esc(path)}" alt="${esc(alt)}" class="${cls}">`;
const btn=(label,action,args='',cls='',disabled=false)=>`<button class="${cls}" data-action="${action}" data-args="${esc(args)}" ${disabled?'disabled':''}>${esc(label)}</button>`;
const nameOf=(kind,id)=>data.catalog[kind].find(x=>x.id===id)?.name||id;
const portrait=p=>data.assets.portraits[p.race];const sprite=p=>data.assets.characters[p.race+'_'+p.profession];
const bar=(v,max,type='')=>`<div class="bar ${type}"><i style="width:${Math.max(0,Math.min(100,v/max*100))}%"></i></div>`;
function save(){if(g?.s){try{localStorage.setItem(KEY,JSON.stringify(g.s))}catch{g.s.notice='瀏覽器儲存空間不足，請匯出存檔。'}}}
function audio(){if(!sound)return;try{const ctx=new AudioContext(),o=ctx.createOscillator(),a=ctx.createGain();o.type='triangle';o.frequency.value=190;a.gain.setValueAtTime(.03,ctx.currentTime);a.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.1);o.connect(a);a.connect(ctx.destination);o.start();o.stop(ctx.currentTime+.12);o.onended=()=>ctx.close()}catch{}}
async function boot(){const files=['assets/manifest.json','data/npc-catalog.json','data/oracles.json','data/events.json','data/building-events.json','data/traits.json','assets/encounters.json'];const v=await Promise.all(files.map(f=>fetch(f).then(r=>{if(!r.ok)throw Error(f);return r.json()})));data={assets:v[0],catalog:v[1],oracles:v[2],events:v[3],buildings:v[4],traits:v[5],encounters:v[6]};g=new Game(data);g.recordVisuals=true;render()}
function car(v,party,classes=''){const base=data.assets.vehicles[v.model],a={...base,...base.variants?.[base.seats+(v.mods||[]).filter(x=>x==='seat').length]};return `<div class="vehicle ${classes}">${a.windows.map((w,i)=>party[i]?`<img class="passenger" src="assets/${portrait(party[i])}" alt="${esc(display(party[i]))}" style="left:${w.x/160*100}%;top:${w.y/72*100}%;width:${Math.min(w.width,w.height)/160*100}%">`:'').join('')}${img(a.image,a.name,'body')}${v.mods?.filter(x=>x==='gun'||x==='lamp').slice(0,1).map(x=>img(data.assets.mods[x],MODS[x].name,'mod')).join('')}</div>`}
function worldPicture(id,cls=''){const a=data.assets.worlds[id];return `<svg class="painted-panorama ${cls}" viewBox="${a.rect.join(' ')}" role="img" aria-label="${esc(BIOMES.find(b=>b.id===id)?.name||id)} · 外星佔領區"><image href="assets/${a.image}" width="${a.size[0]}" height="${a.size[1]}"/></svg>`}
function intro(){let saved=null;try{saved=JSON.parse(localStorage.getItem(KEY))}catch{}return `<div class="intro"><div class="eyebrow">A ROAD THROUGH THE AFTERMATH</div><h1>一路向東</h1><p>外星軍團佔領了地球。<br>你還有一輛車，和一個向東的理由。</p><div class="intro-scene">${worldPicture('city')}${img(data.assets.vehicles.sedan.image,'往東行駛的車','intro-car')}</div>${creationChoices(data,selectedRace,selectedJob)}<div class="new-preview">${img(data.assets.characters[selectedRace+'_'+selectedJob],'你的角色')}<div><h3>${nameOf('races',selectedRace)} · ${nameOf('professions',selectedJob)}</h3>${['race_'+selectedRace,'profession_'+selectedJob].map(id=>{const t=data.traits.advantages.find(t=>t.id===id);return `<p class="starting-trait"><b>${esc(t.name)}</b>${esc(t.effect)}</p>`;}).join('')}<p>名字、外號與一項缺點由神諭決定。</p></div></div><div class="actions">${btn('開始新的旅程','start','','primary')}${saved?btn(`繼續旅程 · 進度 ${saved.progress}/100`,'load'):''}</div><div class="footer-note">單人遊戲 · 自動保存在此瀏覽器<br><a href="art.html" target="_blank">像素圖鑑</a></div></div>`}
function partyStrip(battle=false){const s=presentation||g.s,actor=battle&&!presentation?g.commandActor():null,allyTarget=pendingCommand?.allies,clickable=allyTarget||!battle;return `<div class="party-strip ${battle?'battle-party':''}" aria-label="${battle?'我方隊員':'同行者狀態'}">${s.party.map(p=>{const order=s.battle?.orders?.[p.id],orderName={attack:'攻擊',defend:'防禦',medicine:'藥品',escape:'逃跑',psi:'超能力'}[order?.type];return `<${clickable?'button':'div'} data-person="${p.id}" class="member ${p.id===actor?.id?'active':''} ${p.hp<=0?'fallen':''} ${allyTarget?'ally-target':''}" ${clickable?`data-action="${allyTarget?'targetAlly':'openPerson'}" data-args="${p.id}" ${allyTarget&&p.hp<=0?'disabled':''}`:''}>${img(portrait(p),display(p))}<span class="name">${p.id===s.driver&&!battle?'▸ ':''}${esc(display(p))}</span><span>HP <b>${p.hp}</b>/${p.maxHp}${bar(p.hp,p.maxHp,'hp')}</span><span>體力 ${p.st}/${p.maxSt}${bar(p.st,p.maxSt)}</span><span>ESP ${p.esp}/${p.maxEsp}${bar(p.esp,p.maxEsp,'esp')}</span>${battle?`<span class="order-state">${p.hp<=0?'倒下':p.asleep?'睡眠':orderName?'✓ '+orderName:p.id===actor?.id?'▸ 選擇指令':'等待指令'}</span>`:''}</${clickable?'button':'div'}>`}).join('')}</div>`}
function hud(){const s=presentation||g.s;return `<header class="brand"><div><span class="label">EASTWARD</span><strong>一路向東</strong></div><div class="journey-readout"><span id="journey-time">第 ${Math.floor(s.minutes/1440)+1} 天 · ${phaseName(s.minutes)}</span><span><b id="journey-speed">0</b> <small>km/h</small> · <span id="journey-place">${biomeAt(s.progress,s.seed).name}</span></span></div></header><div class="status"><div class="status-line"><span>向東 <b>${s.progress}</b> <small>/ 100</small></span><span class="resource">${img(data.assets.icons.fuel,'汽油')} ${s.resources.fuel}</span><span class="resource">${img(data.assets.icons.scrap,'廢料')} ${s.resources.scrap}</span><span class="resource">${img(data.assets.icons.medicine,'藥品')} ${s.resources.medicine}</span></div><div class="progress"><i style="width:${s.progress}%"></i></div></div>${s.battle?'':partyStrip()}`}
function scene(){const s=presentation||g.s,title=s.battle?(s.battle.mode==='vehicle'?'公路追逐':'遭遇戰')+' · ROUND '+s.battle.round:s.mode==='driving'?'沿著公路，繼續向東':s.current?.event.title||'公路 · 準備出發';let hotspots='';if(s.mode==='event'){const option=g.options().find(o=>g.canChoose(o));if(option)hotspots=btn(option.id==='enter'?'進入建築 ↗':option.label+' ↗','choose',option.id,'world-interact');else if(s.current?.dialogue)hotspots=btn('交談 ↗','talk','','world-interact');}if(s.battle){const enemies=presentation?s.battle.enemies:s.battle.enemies.filter(e=>e.hp>0),layout=enemyLayout(enemies.length);hotspots=enemies.map((e,i)=>`<button class="world-target ${e.hp<=0?'defeated':''} ${selectedEnemy===e.id?'selected':''} ${pendingCommand&&!pendingCommand.allies?'await-target':''}" style="left:${layout[i].cx/384*100}%;top:21%" data-action="targetEnemy" data-args="${e.id}" aria-label="${pendingCommand&&!pendingCommand.allies?'對':'鎖定'}${esc(e.name)}"><span class="enemy-caption"><span>${esc(e.name)}</span><small>HP ${e.hp}/${e.maxHp}</small>${bar(e.hp,e.maxHp,'hp')}</span></button>`).join('');}return `<section class="scene world-stage ${s.mode==='driving'?'driving':''} ${s.battle?'battle-stage':''}"><canvas id="world-canvas" width="384" height="240" role="img" aria-label="公路遊戲場景"></canvas><div class="scene-badge" ${s.mode==='driving'?'id="drive-status"':''}>${esc(title)}</div><span class="compass">${s.battle?'VS':'E →'}</span>${hotspots}</section>`}
function combatBody(){const s=g.s,p=g.commandActor(),orders=Object.keys(s.battle.orders||{}),reserved=Object.values(s.battle.orders||{}).filter(o=>o.type==='medicine').length;let commands='';
 if(!p)commands=btn('等待敵方行動','combat','defend','primary');
 else if(pendingCommand)commands=`<p class="target-hint">${pendingCommand.allies?'點選上方隊員，選擇治療對象':'點選畫面中的敵人，確認目標'}</p>${btn('返回指令','cancelCommand','','quiet')}`;
 else if(combatMenu==='psi')commands=`<div class="psi-list">${learned(p).map(pow=>btn(pow.name+' · '+pow.cost+' ESP','psi',pow.id,'',p.esp<pow.cost)).join('')}${btn('返回指令','cancelCommand','','quiet')}</div>`;
 else commands=`<div class="command-grid">${btn('⚔ 攻擊','combat','attack','primary')}${btn('✧ 超能力','psiMenu','','',s.battle.mode!=='character'||!learned(p).length)}${btn('✚ 藥品 '+(s.resources.medicine-reserved),'combat','medicine','',s.resources.medicine<=reserved)}${btn('◇ 防禦','combat','defend')}${btn('↗ 逃跑','combat','escape')}${btn('↶ 上一人','undoOrder','','quiet',!orders.length)}</div>`;
 return `<div class="content battle-controls"><div class="command-heading"><strong>${p?esc(display(p)):'隊員無法行動'}</strong><span>${s.battle.mode==='vehicle'?'車況 '+s.vehicle.hp+'/'+s.vehicle.maxHp:orders.length+' 人已選指令'}</span></div>${commands}</div>`}
function body(){const s=g.s;if(s.mode==='driving')return `<div class="content"><div class="event-top"><h2>繼續向東</h2><span class="roll-chip">D10 · ${s.travel.die}</span></div><p class="event-text">車輪壓過破碎的道路。<br>前進 ${s.travel.n} · 汽油 −${s.travel.cost.fuel} · 體力 −${s.travel.cost.st}</p><button class="skip-drive" data-action="skipDrive">略過行車動畫 ›</button></div>`;
 if(s.mode==='ready')return `<div class="content ready-controls"><div class="event-top"><h2>下一段路</h2><span class="tag">${s.party.length} 人 · ${g.seats()} 席</span></div><p class="event-text">${s.resources.fuel<=0?'油箱已空，必須尋找燃料或另一輛車。':g.driver()?.st<=0?'駕駛已無體力。換人或讓隊伍睡一覺。':s.vehicle.hp<=0?'車已無法行駛，必須尋找替代車輛。':'不知道前面會遇到什麼。繼續向東吧。'}</p><div class="actions">${btn('發動引擎 · 擲 D10','depart','','primary',!g.canDrive())}${btn('休息與守夜','panel','sleep')}${s.resources.fuel<=0||s.vehicle.hp<=0?btn('尋找出路','search'):''}</div></div>`;
 if(s.mode==='combat')return combatBody();
 const c=s.current;if(!c)return '';const ev=c.event;let actions='';if(c.dialogue){actions=btn('交談','talk')+btn('交易／服務','panel','shop','',!c.service)+btn('邀請同行','recruit','','',s.party.length>=g.seats())+btn('攻擊','attackNpc','','danger');}else actions=g.options().map(o=>btn(o.label+Object.entries(g.optionCosts(g.preparedOption(o))).map(([k,v])=>' · '+v+' '+({fuel:'汽油',scrap:'廢料',medicine:'藥品',stamina:'體力'}[k]||k)).join(''),'choose',o.id,'',!g.canChoose(o))).join('');
 actions+=g.traitActions().map(a=>btn(a.label,'trait',a.id)).join('');if(c.inside&&!c.explored&&!c.event.options?.length)actions+=btn('探索建築其他區域','explore');if(s.offerVehicle)actions+=btn('查看可用車輛','panel','offer','primary');const canFinish=!c.building&&(!c.event.options?.length||c.dialogue);actions+=canFinish?btn(s.strandedSearch?'結束尋找出路':'結束這個事件','finish','','primary'):'';
 return `<div class="content"><div class="event-top"><h2>${esc(ev.title)}</h2><span class="roll-chip">${esc(s.dice?.kind)} ${s.dice?.value||''}</span></div>${peoplePicker(g,data,g.actor()?.id,'selectActor','事件執行者',p=>p.hp>0&&!p.asleep)}${c.npc?`<div class="subtitle">${esc(display(c.npc))} · ${nameOf('races',c.npc.race)}／${nameOf('professions',c.npc.profession)} · ${c.npc.attitude}</div>`:''}<details class="event-notes"><summary>查看現場描述</summary><p>${esc(ev.text.replace('{npc.display_name}',c.npc?display(c.npc):'旅人'))}</p></details><div class="actions">${actions}</div></div>`}
function panelHtml(){if(!panel)return '';const s=g.s;let title='',content='';if(panel==='party'){title='角色與裝備';content=characterPanel(g,data,ui);}
 if(panel?.startsWith('dismiss:')){const p=s.party.find(p=>p.id===panel.split(':')[1]);title='讓同伴離開';content=`<p>確定讓 ${esc(display(p))} 離開？他會帶走身上的裝備。去向由神諭決定，將來可能再度相遇。</p><div class="actions">${btn('讓他離開','dismiss',p.id,'danger')}${btn('留下','panel','party')}</div>`}
 if(panel==='bag'){title='裝備與背包';content=inventoryPanel(g,data,ui);}
 if(panel==='vehicle'){title='你的車';const v=data.assets.vehicles[s.vehicle.model];content=`${img(v.image,v.name)}<h3>${v.name}</h3><p>車況 ${s.vehicle.hp}/${s.vehicle.maxHp} · 座位 ${s.party.length}/${g.seats()}</p><p>改裝 ${s.vehicle.mods.length}/${v.modSlots}：${s.vehicle.mods.map(k=>MODS[k].name).join('、')||'尚無'}</p><p class="event-text">維修與改裝必須透過修車廠事件。座位不足時，需要選擇讓誰離開。</p>${s.offerVehicle?btn('查看新車','panel','offer'):''}`}
 if(panel==='offer'){title='替代車輛';const o=s.offerVehicle;if(o){const v=data.assets.vehicles[o.model];content=`${img(v.image,v.name)}<h3>${v.name}</h3><p>${v.seats} 席 · 車況 ${o.hp}/${o.maxHp} · 剩餘汽油 ${o.fuel}</p><p class="event-text">換車時公共背包保留，舊車固定改裝不轉移。</p>${s.party.length>v.seats?`<p class="notice">需要先遣散 ${s.party.length-v.seats} 名同伴。</p>${btn('管理同伴','panel','party')}`:btn('換上這輛車','replace','','primary')}`}}
 if(panel==='journal'){title='旅途紀錄';content=`<div class="card"><h3>${s.world.archive}</h3><p class="tiny">這一局的世界，正在透過你的發現逐漸成形。</p>${s.history.map(t=>`<p class="event-text">${esc(t)}</p>`).join('')||'<p class="tiny">尚未取得歷史紀錄。</p>'}</div>${s.logs.map(l=>`<div class="log"><small>進度 ${l.progress} · ${l.title}</small><p>${esc(l.text)}</p></div>`).join('')}`}
 if(panel==='sleep'){title='休息與守夜';content=watchPanel(g,data,ui);}
 if(panel==='shop'){title='交易與服務';const shop=s.current?.service;const items=[];if(shop==='npc_trade'){const npc=s.current.npc,stock=npc.stock||{fuel:1,medicine:1,item:1};if(stock.fuel)items.push(['10 點汽油 · '+g.price(3)+' 廢料','fuel:']);if(stock.medicine)items.push(['1 份藥品 · '+g.price(2)+' 廢料','medicine:']);const item=npc.tradeItem||'tools';if(stock.item)items.push([ITEMS[item].name+' · '+g.price(ITEMS[item].price)+' 廢料','item:'+item]);}if(['fuel_shop','general_shop'].includes(shop))items.push(['10 點汽油 · '+g.price(3)+' 廢料','fuel:']);if(['pharmacy','general_shop','clinic'].includes(shop))items.push(['1 份藥品 · '+g.price(2)+' 廢料','medicine:']);if(['general_shop','equipment_shop'].includes(shop))Object.entries(ITEMS).forEach(([id,it])=>items.push([it.name+' · '+g.price(it.price)+' 廢料','item:'+id]));if(shop==='garage'){items.push(['維修車輛 · 2 廢料','repair:']);Object.entries(MODS).forEach(([id,m])=>items.push(['安裝'+m.name+' · '+m.price+' 廢料','mod:'+id]))}if(shop==='clinic')items.push(['治療全隊 · 2 廢料','heal:']);if(shop==='hotel')items.push(['安全住宿 · 3 廢料','hotel:']);if(shop==='vehicle_shop')Object.entries(data.assets.vehicles).forEach(([id,v])=>items.push([v.name+' · '+g.price(10+v.seats*2)+' 廢料','vehicle:'+id]));content=`<p class="shop-wallet">持有 <b>${s.resources.scrap}</b> 廢料 · 交易者 ${esc(display(g.actor()))}</p>${items.some(([,a])=>a.startsWith('item:'))?peoplePicker(g,data,inspectedPerson(g,ui).id,'inspectPerson','裝備比較對象'):''}${ui.shopItemId?comparisonCard(g,data,ui,ui.shopItemId,{shop:true}):''}<div class="actions shop-items">${items.map(([l,a])=>a.startsWith('item:')?`<button class="shop-equipment" data-action="inspectShopItem" data-args="${a.split(':')[1]}"><strong>${esc(l)}</strong><small>${itemBonuses(a.split(':')[1])}</small><span>查看裝備比較 ›</span></button>`:btn(l,'buy',a)).join('')}</div>`}
 return `<div class="panel-back" data-panel="${esc(panel)}"><section class="panel game-panel" role="dialog" aria-modal="true" aria-labelledby="panel-title"><div class="panel-header"><div><small>EASTWARD / TRAVELLERS</small><h2 id="panel-title" tabindex="-1">${title}</h2></div>${btn('關閉','close','','quiet')}</div>${ui.feedback?`<div class="panel-feedback" role="status">${esc(ui.feedback)}</div>`:''}${content}</section></div>`}
function render(){if(!data)return;const oldDialog=root.querySelector('.panel-back'),oldPanel=oldDialog?.dataset.panel,oldScroll=oldDialog?.scrollTop||0;if(!g.s){root.className='';root.innerHTML=intro()+choiceDialog(data,ui.picker,selectedRace,selectedJob);restoreDialog(oldPanel,oldScroll);return;}const s=presentation||g.s;root.className=(s.mode==='combat'?'in-combat':'')+(presentation?' is-playing':'');
 if(s.mode!=='combat'){pendingCommand=null;combatMenu='root';}
 if(s.mode==='ending'){root.innerHTML=`<div class="ending"><span class="label">END OF THE ROAD</span><h1>${s.end.win?'抵達末日綠洲':'旅程到此為止'}</h1>${worldPicture(s.end.win?'oasis':'salt')}<p>${esc(s.end.text)}</p><p class="muted">走到 ${s.progress}/100 · ${s.stop} 次停靠 · ${new Set(s.seen).size} 種發現</p><div class="actions">${btn('閱讀旅途紀錄','panel','journal')}${btn('再走一段不同的路','new','','primary')}${btn('匯出這段旅程','export')}</div></div>${panelHtml()}`;restoreDialog(oldPanel,oldScroll);save();return;}
 if(s.mode==='driving'&&!s.travel.preview)s.travel.preview=g.previewArrival();
 const message=`<div class="dialogue ${s.battle?'battle-dialogue':''}" ${s.battle?'aria-live="polite"':''}><span class="speaker">${s.mode==='driving'?'車內 · 日常':s.battle?'戰況':'旅途訊息'}</span>${esc(presentation?playbackLabel:s.notice)}</div>`;
 root.innerHTML=hud()+scene()+(s.battle?partyStrip(true)+(presentation?`<div class="content battle-controls playback-controls"><div class="command-heading"><strong>行動進行中</strong><span>依速度順序出手</span></div><div class="playback-track"><i></i></div>${btn('略過本輪動畫 ›','skipPlayback','','quiet')}</div>`:body())+message:message+body())+`<nav class="nav">${btn('同行者','panel','party')}${btn('背包','panel','bag')}${btn('車輛','panel','vehicle')}${btn('紀錄','panel','journal')}${btn(reducedMotion()?'柔和動畫':'完整動畫','motion','','motion-toggle')}</nav>${panelHtml()}`;
 restoreDialog(oldPanel,oldScroll);save();if(s.mode==='driving'&&!timer){travelStarted=performance.now();timer=setTimeout(()=>{timer=null;const before=structuredClone(g.s);resetVisuals();g.arrive();presentChange(before,'arrive').catch(console.error)},12000);}mountWorld(document.getElementById('world-canvas'),s,data.assets,data.encounters,{duration:12000,travelStart:travelStarted,target:selectedEnemy,playback:!!presentation});
 if(presentation){root.querySelectorAll('button:not([data-action="skipPlayback"]),select').forEach(el=>el.disabled=true);}
 if(s.battle){const active=root.querySelector('.battle-party .active');if(active)active.parentElement.scrollLeft=Math.max(0,active.offsetLeft-active.parentElement.offsetLeft-12);}}
function restoreDialog(previous,scroll){const modal=root.querySelector('.panel-back');document.body.classList.toggle('has-dialog',!!modal);for(const el of root.children)el.inert=!!modal&&el!==modal;
 if(!modal)return;modal.scrollTop=modal.dataset.panel===previous?scroll:0;
 if(modal.dataset.panel!==previous)modal.querySelector('h2')?.focus({preventScroll:true});
 for(const track of modal.querySelectorAll('.people-picker')){const selected=track.querySelector('.selected');if(selected)track.scrollLeft=Math.max(0,selected.offsetLeft-track.offsetLeft-12);}
 if(ui.scrollTop){modal.scrollTop=0;ui.scrollTop=false;}
 if(ui.scrollCompare){ui.scrollCompare=false;modal.querySelector('#equipment-comparison')?.scrollIntoView({block:'nearest',behavior:'instant'});}
}
root.addEventListener('keydown',e=>{const modal=root.querySelector('[role="dialog"]');if(!modal)return;if(e.key==='Escape'){e.preventDefault();panel=null;ui.picker=null;render();return;}if(e.key==='Tab'){const focus=[...modal.querySelectorAll('button:not(:disabled),[tabindex="0"],summary')];if(!focus.length)return;const first=focus[0],last=focus.at(-1);if(e.shiftKey&&(document.activeElement===first||!focus.includes(document.activeElement))){e.preventDefault();last.focus();}else if(!e.shiftKey&&(document.activeElement===last||!focus.includes(document.activeElement))){e.preventDefault();first.focus();}}});
function resetVisuals(){g.visualSteps=[];g.visualStart=null;}
async function presentChange(before,effectType){
 const steps=g.visualSteps||[],start=g.visualStart,transition=transitionFor(before,g.s),visualBefore=before?captureVisual(before):null;
 resetVisuals();save();
 if(!steps.length&&!transition){render();if(visualBefore&&g.s)animateResult(visualBefore,g.s,effectType);return;}
 busy=true;pendingCommand=null;combatMenu='root';panel=null;
 try{
  if(steps.length){
   presentation=start;playbackLabel='準備行動…';playbackController=new AbortController();
   await sceneTransition(transition,transition==='battle'?'遭遇戰':'走進建築',()=>render());
   for(const step of steps){
    if(playbackController.signal.aborted)break;
    playbackLabel=step.name+' · '+({attack:'攻擊',psi:'超能力',medicine:'使用藥品',defend:'防禦',escape:'試著脫離',stun:'無法行動'}[step.kind]||'行動');
    render();playBattleBeat(step);
    await waitForBeat(220,playbackController.signal);if(playbackController.signal.aborted)break;
    applyBattleFrame(presentation,step.after);playbackLabel=step.name+'：'+step.label;render();
    for(const hit of step.effects.filter(e=>e.side==='party')){const el=root.querySelector(`[data-person="${hit.id}"]`);el?.classList.add(hit.amount<0?'was-hit':'was-healed');if(el){const amount=document.createElement('span');amount.className='damage-number'+(hit.amount>0?' heal':'');amount.textContent=(hit.amount>0?'+':'')+hit.amount;el.append(amount);}if(el)el.parentElement.scrollLeft=Math.max(0,el.offsetLeft-el.parentElement.offsetLeft-12);}
    await waitForBeat(400,playbackController.signal);
   }
  }else await sceneTransition(transition,transition==='battle'?'遭遇戰':transition==='leave'?'回到公路':g.s.current?.event.title||'走進建築',()=>render());
 }finally{presentation=null;playbackController=null;clearBattleBeat();busy=false;render();}
}
function commitCommand(target){if(!pendingCommand)return;const {allies,...command}=pendingCommand;if(g.combatRound({...command,target})){pendingCommand=null;combatMenu='root';}}
root.addEventListener('click',async e=>{if(e.target.classList.contains('panel-back')&&!busy){panel=null;ui.picker=null;render();return;}const b=e.target.closest('button[data-action]');if(!b||b.disabled)return;const {action:a,args:x}=b.dataset;if(a==='skipPlayback'){playbackController?.abort();return;}if(busy)return;try{const before=g.s?structuredClone(g.s):null;resetVisuals();const effectType=pendingCommand?.type==='psi'||Object.values(g.s?.battle?.orders||{}).some(o=>o.type==='psi')?'psi':a==='combat'?x:a;audio();switch(a){case 'motion':toggleMotion();break;case 'start':ui.personId=null;ui.feedback='';g.start({race:selectedRace,profession:selectedJob});break;case 'load':{const s=JSON.parse(localStorage.getItem(KEY));if(s?.version!==1)throw Error('存檔版本不相容');g=new Game(data,s);g.recordVisuals=true;break;}case 'new':g.s=null;panel=null;break;case 'panel':panel=x;ui.feedback='';ui.shopItemId=null;if(x==='bag'){ui.slot='全部';ui.itemId=null;}if(x==='sleep')ui.watchId=null;break;case 'close':panel=null;ui.feedback='';break;case 'depart':g.depart();break;case 'skipDrive':if(g.s.mode==='driving'){clearTimeout(timer);timer=null;g.arrive();}break;case 'choose':g.choose(x);break;case 'explore':g.exploreBuilding();break;case 'finish':g.s.strandedSearch?g.resolveSearch():g.finishEvent();break;case 'talk':g.talk();break;case 'trait':g.traitAction(x);break;case 'recruit':g.recruit();break;case 'attackNpc':g.beginCombat('character',null,g.s.current.npc);break;case 'driver':g.changeDriver(x);ui.feedback=g.s.notice;break;case 'heal':g.useMedicine(x);ui.feedback=g.s.notice;break;case 'dismissAsk':panel='dismiss:'+x;break;case 'dismiss':g.dismiss(x);panel='party';break;case 'openPerson':ui.personId=x;panel='party';ui.feedback='';break;case 'inspectPerson':ui.personId=x;ui.feedback='';break;case 'selectActor':g.selectActor(x);break;
case 'gearSlot':panel='bag';ui.slot=x;ui.itemId=null;ui.feedback='';break;case 'gearFilter':ui.slot=x;ui.itemId=null;ui.feedback='';break;
case 'inspectItem':ui.itemId=x;ui.feedback='';ui.scrollCompare=true;break;case 'inspectShopItem':ui.shopItemId=x;ui.feedback='';ui.scrollCompare=true;break;
case 'confirmEquip':{const p=inspectedPerson(g,ui),preview=equipmentPreview(g,p,x);if(preview?.owned&&!preview.same&&p.hp>0&&g.equip(p.id,x)){const changes=preview.stats.filter(v=>v.delta).map(v=>`${v.name} ${v.before} → ${v.after}`).join('、');ui.feedback=`${display(p)}已換上${ITEMS[x].name}。${changes}。${preview.previous?ITEMS[preview.previous].name+'已放回公共背包。':''}`;ui.itemId=null;ui.scrollTop=true;}else ui.feedback='目前無法更換這件裝備。';break;}
case 'watch':ui.watchId=x||null;break;case 'openPicker':ui.picker=x;break;case 'closePicker':ui.picker=null;break;case 'pickRace':selectedRace=x;ui.picker=null;break;case 'pickJob':selectedJob=x;ui.picker=null;break;
case 'buy':{const [kind,id]=x.split(':');if(!g.buy(kind,id))g.tell('物資不足、改裝格已滿，或目前不能使用這項服務。');ui.feedback=g.s.notice;if(kind==='item'&&ui.feedback==='交易完成。'){ui.feedback='已購買'+ITEMS[id].name+'，存放在公共背包。';ui.shopItemId=null;}if(g.s.offerVehicle)panel='offer';break;}case 'replace':g.replaceVehicle();panel=null;break;case 'sleep':g.sleep(ui.watchId);panel=null;break;case 'search':g.searchStranded();break;case 'targetEnemy':selectedEnemy=x;if(pendingCommand&&!pendingCommand.allies)commitCommand(x);break;case 'targetAlly':if(pendingCommand?.allies)commitCommand(x);break;case 'cancelCommand':pendingCommand=null;combatMenu='root';break;case 'undoOrder':{const ids=Object.keys(g.s.battle.orders||{});if(ids.length)delete g.s.battle.orders[ids.at(-1)];pendingCommand=null;combatMenu='root';break;}case 'psiMenu':combatMenu='psi';break;case 'combat':if(['defend','escape'].includes(x)){g.combatRound({type:x});combatMenu='root';}else pendingCommand={type:x,allies:x==='medicine'};break;case 'psi':{const pow=learned(g.commandActor()).find(p=>p.id===Number(x));if(!pow)break;if(['shield','burst'].includes(pow.type)){g.combatRound({type:'psi',power:x});combatMenu='root';}else pendingCommand={type:'psi',power:x,allies:pow.type==='heal'};break;}case 'export':{const blob=new Blob([JSON.stringify(g.s,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='一路向東-旅程存檔.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}}await presentChange(before,effectType)}catch(err){console.error(err);if(g.s){g.s.notice='操作未完成：'+err.message;render()}}});
boot().catch(e=>{root.innerHTML=`<div class="error">資料載入失敗，請重新整理。<br>${esc(e.message)}</div>`;console.error(e)});
